def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = set(v for row in grid for v in row) - {bg, 0}
    for color in colors:
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr, dc in ((1, 1), (1, -1)):
            groups = {}
            for r, c in points:
                key = r - c if dc == 1 else r + c
                groups.setdefault(key, []).append((r, c))
            for pts in groups.values():
                if len(pts) < 2:
                    continue
                # Extend the line from its extreme points, stopping at any other color.
                lo, hi = sorted(pts, key=lambda p: p[0])[0], sorted(pts, key=lambda p: p[0])[-1]
                r, c = lo[0] - dr, lo[1] - dc
                while 0 <= r < h and 0 <= c < w and out[r][c] == bg:
                    out[r][c] = color
                    r, c = r - dr, c - dc
                r, c = hi[0] + dr, hi[1] + dc
                while 0 <= r < h and 0 <= c < w and out[r][c] == bg:
                    out[r][c] = color
                    r, c = r + dr, c + dc
    return out

